"""##Providers de IA"""

class BaseLLMProvider:
    def __init__(self, model_name, **kwargs):
        self.model_name = model_name
        self.config = kwargs
    def generate(self, prompt, max_tokens=1000, temperature=0.7):
        raise NotImplementedError("Subclass must implement generate()")

class OpenAIProvider(BaseLLMProvider):
    def __init__(self, model_name, **kwargs):
        super().__init__(model_name, **kwargs)
        self.client = openai.OpenAI(
            api_key=kwargs.get('api_key'),
            base_url=kwargs.get('base_url')
        )
    def generate(self, prompt, max_tokens=1000, temperature=0.7):
        response = self.client.chat.completions.create(
            model=self.model_name,
            messages=[{'role': 'user', 'content': prompt}],
            max_tokens=max_tokens,
            temperature=temperature
        )
        return response.choices[0].message.content

class AnthropicProvider(BaseLLMProvider):
    def __init__(self, model_name, **kwargs):
        super().__init__(model_name, **kwargs)
        self.client = anthropic.Anthropic(api_key=kwargs.get('api_key'))
    def generate(self, prompt, max_tokens=1000, temperature=0.7):
        response = self.client.messages.create(
            model=self.model_name,
            max_tokens=max_tokens,
            messages=[{'role': 'user', 'content': prompt}],
            temperature=temperature
        )
        return response.content[0].text

class GoogleProvider(BaseLLMProvider):
    def __init__(self, model_name, **kwargs):
        super().__init__(model_name, **kwargs)
        self.client = genai.Client(api_key=kwargs.get('api_key'))
        self.model_id = model_name

    def generate(self, prompt, max_tokens=8192, temperature=0.1):
        effective_tokens = max(max_tokens, 8192)
        try:
            response = self.client.models.generate_content(
                model=self.model_id,
                contents=prompt,
                config=types.GenerateContentConfig(
                    max_output_tokens=effective_tokens,
                    temperature=temperature,
                    response_mime_type='application/json',
                    system_instruction="Eres un exportador de datos JSON puro. No expliques, no razones, no pienses en voz alta. Genera directamente el JSON solicitado."
                )
            )
            if response.candidates and response.candidates[0].finish_reason == 'MAX_TOKENS':
                print(f"⚠️ CRÍTICO: El modelo agotó los {effective_tokens} tokens. El JSON estará incompleto.")
            text = response.text
            if not text: return '[]'
            clean_text = re.sub(r'```json\s?|```', '', text).strip()
            if not (clean_text.startswith('{') or clean_text.startswith('[')):
                 return f'{{"error": "Respuesta inválida", "raw": "{clean_text[:100]}"}}'
            return clean_text
        except Exception as e:
            error_msg = str(e).replace('"', "'")
            return f'{{"error": "Fallo en Gemini: {error_msg}"}}'
PROVIDER_REGISTRY = {
    'openai': OpenAIProvider,
    'anthropic': AnthropicProvider,
    'google': GoogleProvider,
}
def create_llm_provider(provider_type, model_name, **kwargs):
    if provider_type not in PROVIDER_REGISTRY:
        raise ValueError(f"Proveedor desconocido: {provider_type}")
    return PROVIDER_REGISTRY[provider_type](model_name, **kwargs)

"""##Definición de PROMPT"""

SERIOUS_GAMES_PROMPT = """You are an expert recommendation system for gamified serious games.

Available components:
{context}

User query:
{query}

Instructions:
1. Select exactly ONE serious game design ONLY from the 'Available components' list. The recommendation's title MUST exactly match one of the titles in the 'Available components' list.
2. Keep the 'justification' and 'description' concise (under 3 sentences).
3. Ensure the JSON is properly formatted.

Output format:
[
  {{
    "recommendation": "Name",
    "ranking": 0.95,
    "description": "Concise explanation",
    "source": "database",
    "sector": "Sector",
    "context": "Context",
    "dynamics": {{
      "progression": "Description",
      "emotion": "Description",
      "cognitive": "Description",
      "motivation": "Description"
    }},
    "mechanics": ["M1", "M2"],
    "elements": ["E1", "E2"],
    "narrative": "Story",
    "justification": "Alignment reasoning"
  }}
]
"""
PROMPTS = {'serious_games': SERIOUS_GAMES_PROMPT}

"""##Carga interacción del usuario"""

def load_serious_games_ratings():
    try:
        elements_i = pd.read_csv("dataset/elementsIntervention.csv").rename(columns=lambda x: x.strip())
        dynamics_i = pd.read_csv("dataset/dynamicsIntervention.csv").rename(columns=lambda x: x.strip())
        mechanics_i = pd.read_csv("dataset/mechanicsIntervention.csv").rename(columns=lambda x: x.strip())
        narratives_i = pd.read_csv("dataset/narrativesIntervention.csv").rename(columns=lambda x: x.strip())

        elements_i = elements_i.rename(columns={"elementId": "item_id"})
        elements_i["item_type"] = "element"
        dynamics_i = dynamics_i.rename(columns={"dynamicId": "item_id"})
        dynamics_i["item_type"] = "dynamic"
        mechanics_i = mechanics_i.rename(columns={"mechanicId": "item_id"})
        mechanics_i["item_type"] = "mechanic"
        narratives_i = narratives_i.rename(columns={"narrativeId": "item_id"})
        narratives_i["item_type"] = "narrative"

        ratings_df = pd.concat([elements_i, dynamics_i, mechanics_i, narratives_i], ignore_index=True)

        if 'item_id' not in ratings_df.columns:
            id_cols = [c for c in ratings_df.columns if 'Id' in c]
            if id_cols: ratings_df['item_id'] = ratings_df[id_cols[0]]
            else: raise KeyError("No valid ID column found in intervention files.")

        ratings_df["item_id"] = ratings_df["item_id"].astype(str).str.strip()
        ratings_df["item_type"] = ratings_df["item_type"].astype(str).str.strip().str.lower()
        ratings_df["global_item_id"] = ratings_df["item_type"] + "_" + ratings_df["item_id"]

        if "userId" not in ratings_df.columns: raise KeyError("Column 'userId' not found in intervention files.")
        if "rating" not in ratings_df.columns: raise KeyError("Column 'rating' not found in intervention files.")
        return ratings_df
    except Exception as e:
        print(f"   ☑′ Using fallback synthetic ratings due to: {e}")
        return pd.DataFrame({'userId': [1]*5, 'item_id': [1,2,3,4,5], 'item_type': ['dynamic']*5, 'rating': [5,4,5,4,5], 'global_item_id': ['dynamic_1','dynamic_2','dynamic_3','dynamic_4','dynamic_5']})

"""##Funciones de apoyo para balanceo"""

def calculate_weights(user_id=None, dataset_name='serious_games'):
    num_llms = len(ACTIVE_LLMS)
    if num_llms == 0: raise ValueError("No hay LLMs activos. Configure al menos una API key.")

    if user_id is None:
        weight_per_llm = 1.0 / num_llms
        return {'llm': 1.0, 'fcd': 0.0, 'llm_individual': {llm_name: weight_per_llm for llm_name in ACTIVE_LLMS.keys()}}

    try:
        ratings_df = load_serious_games_ratings()
        user_ratings = ratings_df[ratings_df['userId'] == user_id]
        n_ratings = len(user_ratings)
    except:
        n_ratings = 0

    if n_ratings < 5: weight_llm, weight_fcd, user_profile = 0.90, 0.10, 'new_user'
    elif n_ratings < 20: weight_llm, weight_fcd, user_profile = 0.70, 0.30, 'active_user'
    else: weight_llm, weight_fcd, user_profile = 0.60, 0.40, 'veteran_user'

    weight_per_llm = weight_llm / num_llms
    if VERBOSE:
        print(f"\n⚖️ Balanceo adaptativo (Serious Games - user {user_id}):")
        print(f"   📊 Intervenciones: {n_ratings} → perfil '{user_profile}'")
        print(f"   📊 Pesos: {weight_llm*100:.0f}% LLM, {weight_fcd*100:.0f}% FCD")

    return {
        'llm': weight_llm, 'fcd': weight_fcd,
        'llm_individual': {llm_name: weight_per_llm for llm_name in ACTIVE_LLMS.keys()},
        'user_profile': user_profile, 'n_ratings': n_ratings
    }

def fuzzy_match_title(title, df, threshold=0.85):
    if USE_RAPIDFUZZ:
        try:
            from rapidfuzz import process, fuzz
            result = process.extractOne(title, df['title'].tolist(), scorer=fuzz.ratio, score_cutoff=threshold * 100)
            if result:
                matched_title, score_100, idx = result
                return matched_title, score_100 / 100, df.iloc[idx]
            return None, 0, None
        except ImportError: pass

    from difflib import SequenceMatcher
    best_match, best_score, best_item = None, 0, None
    title_clean = title.lower().strip()
    for idx, row in df.iterrows():
        db_title = row['title'].lower().strip()
        similarity = SequenceMatcher(None, title_clean, db_title).ratio()
        if similarity > best_score:
            best_score, best_match, best_item = similarity, row['title'], row
    if best_score >= threshold: return best_match, best_score, best_item
    return None, best_score, None

"""##Funciones para el LLM"""

def build_context(items, dataset_name):
    lines = []
    for i, row in items.iterrows():
        lines.append(f"{i+1}. [{row['id']}] {row['title']} - {row['description']}")
    return '\n'.join(lines)


def call_llm(llm_name, prompt):
    config = ACTIVE_LLMS[llm_name]
    for attempt in range(RETRY_ATTEMPTS):
        try:
            provider_kwargs = {'api_key': config.get('api_key'), 'base_url': config.get('base_url')}
            provider = create_llm_provider(config['provider'], config['model'], **provider_kwargs)
            return provider.generate(prompt=prompt, max_tokens=MAX_TOKENS, temperature=TEMPERATURE)
        except Exception as e:
            if attempt == RETRY_ATTEMPTS - 1:
                error_msg = f"{str(e)[:150]}"
                if VERBOSE:
                    import traceback
                    print(f"      Full error: {traceback.format_exc()[:300]}")
                return ""
            time.sleep(2 ** attempt)
    return ""

def parse_llm_json(response, llm_name):
    if not response or not response.strip(): return []
    try:
        data = json.loads(response)
        if not isinstance(data, list): return []
        valid_items = []
        for item in data:
            if all(k in item for k in ['recommendation', 'ranking', 'description']):
                valid_items.append({
                    'recommendation': str(item['recommendation']),
                    'ranking': float(item['ranking']),
                    'description': str(item['description']),
                    'source': str(item.get('source', 'database'))
                })
        return valid_items
    except json.JSONDecodeError as e:
        try:
            start, end = response.find('['), response.rfind(']') + 1
            if start != -1 and end > start:
                cleaned = response[start:end]
                data = json.loads(cleaned)
                if isinstance(data, list): return parse_llm_json(cleaned, llm_name)
        except: pass
        try:
            if "Unterminated string" in str(e):
                cleaned = response
                if cleaned.count('"') % 2 != 0:
                    last_bracket = cleaned.rfind(']')
                    if last_bracket > 0: cleaned = cleaned[:last_bracket] + '"' + cleaned[last_bracket:]
                data = json.loads(cleaned)
                if isinstance(data, list): return parse_llm_json(cleaned, llm_name)
        except: pass
        try:
            import re
            objects = re.findall(r'\{[^}]*"recommendation"[^}]*"ranking"[^}]*"description"[^}]*\}', response)
            if objects:
                valid_items = []
                for obj_str in objects:
                    try:
                        obj = json.loads(obj_str)
                        if all(k in obj for k in ['recommendation', 'ranking', 'description']):
                            valid_items.append({'recommendation': str(obj['recommendation']), 'ranking': float(obj['ranking']), 'description': str(obj['description']), 'source': str(obj.get('source', 'database'))})
                    except: continue
                if valid_items: return valid_items
        except: pass
        if VERBOSE: print(f"   ⚠️ {llm_name}: JSON inválido - {str(e)[:150]}")
        return []

def query_all_llms(query, candidates, dataset_name):
    if VERBOSE: print(f"\n🤖 Consultando {len(ACTIVE_LLMS)} LLMs {'en paralelo' if USE_PARALLEL_LLMS else 'secuencialmente'}...")
    context = build_context(candidates, dataset_name)
    prompt = PROMPTS[dataset_name].format(context=context, query=query)
    results = {}

    if USE_PARALLEL_LLMS:
        llm_names = list(ACTIVE_LLMS.keys())
        def call_single_llm(llm_name_local):
            response = call_llm(llm_name_local, prompt)
            parsed = parse_llm_json(response, llm_name_local)
            return llm_name_local, parsed, len(parsed)
        with ThreadPoolExecutor(max_workers=len(llm_names)) as executor:
            future_to_llm = {executor.submit(call_single_llm, llm_name): llm_name for llm_name in llm_names}
            for future in as_completed(future_to_llm):
                llm_name, parsed, count = future.result()
                results[llm_name] = parsed
                status_char = "✅" if count > 0 else "❌"
                msg = f"{count} recomendaciones" if count > 0 else "Sin respuesta"
                if VERBOSE: print(f"   {status_char} {llm_name}: {msg}")
    else:
        for llm_name in ACTIVE_LLMS.keys():
            if VERBOSE: print(f"   🔄 {llm_name}...", end=" ")
            response = call_llm(llm_name, prompt)
            parsed = parse_llm_json(response, llm_name)
            results[llm_name] = parsed
            if VERBOSE: print(f"✅ {len(parsed)} recomendaciones" if parsed else "❌ Sin respuesta")

    total_recs = sum(len(recs) for recs in results.values())
    if VERBOSE: print(f"   📊 Total: {total_recs} recomendaciones de {len(results)} LLMs")
    if VERBOSE:
        print("\n" + "="*70 + "\n📋 PROMPT ENVIADO A LLMs:\n" + "="*70)
        print(prompt[:500] + "..." if len(prompt) > 500 else prompt)
        print("="*70 + "\n📝 RECOMENDACIONES RECIBIDAS:")
        for llm_name, recs in results.items():
            if recs:
                print(f"\n{llm_name.upper()}:")
                for i, rec in enumerate(recs[:3], 1): print(f"  {i}. {rec['recommendation']} (score: {rec['ranking']})")
                if len(recs) > 3: print(f"  ... y {len(recs)-3} más")
            else: print(f"\n{llm_name.upper()}: ❌ Sin recomendaciones")
    return results

def load_user_ratings(dataset_name):
    from scipy.sparse import csr_matrix
    if dataset_name == 'serious_games':
        ratings_df = load_serious_games_ratings()
        item_col = 'global_item_id'
    else: raise ValueError(f"Dataset '{dataset_name}' no soportado")

    if VERBOSE:
        print(f"   ✅ Cargados: {len(ratings_df):,} ratings")
        print(f"   📊 Usuarios: {ratings_df['userId'].nunique():,}")
        print(f"   📊 Items: {ratings_df[item_col].nunique():,}")
        print(f"   📊 Sparsity: {(1 - len(ratings_df) / (ratings_df['userId'].nunique() * ratings_df[item_col].nunique())) * 100:.2f}%")

    unique_users = sorted(ratings_df['userId'].unique())
    unique_items = sorted(ratings_df[item_col].unique())
    user_id_map = {user_id: idx for idx, user_id in enumerate(unique_users)}
    item_id_map = {item_id: idx for idx, item_id in enumerate(unique_items)}

    row_indices = [user_id_map[uid] for uid in ratings_df['userId']]
    col_indices = [item_id_map[iid] for iid in ratings_df[item_col]]
    ratings_values = ratings_df['rating'].values

    n_users, n_items = len(unique_users), len(unique_items)
    user_item_matrix = csr_matrix((ratings_values, (row_indices, col_indices)), shape=(n_users, n_items))
    if VERBOSE: print(f"   ✅ Matriz creada: {user_item_matrix.shape} (sparse)")
    return ratings_df, user_item_matrix, user_id_map, item_id_map


def calculate_user_similarity(user_item_matrix, user_idx, top_k=50):
    from sklearn.metrics.pairwise import cosine_similarity
    user_vector = user_item_matrix[user_idx]
    similarities = cosine_similarity(user_vector, user_item_matrix).flatten()
    similarities[user_idx] = -1
    top_indices = np.argsort(similarities)[-top_k:][::-1]
    similar_users = [(idx, similarities[idx]) for idx in top_indices if similarities[idx] > 0]
    return similar_users


def fcd_recommendations(user_id, dataset_name, ratings_df, user_item_matrix, user_id_map, item_id_map, top_k=30):
    if user_id not in user_id_map: return []
    user_idx = user_id_map[user_id]
    similar_users = calculate_user_similarity(user_item_matrix, user_idx, top_k=50)
    if not similar_users: return []
    if VERBOSE:
        print(f"\n🔍 FCD para usuario {user_id}:")
        print(f"   ✅ {len(similar_users)} usuarios similares encontrados")
    item_col = 'global_item_id'
    user_ratings = ratings_df[ratings_df['userId'] == user_id]
    consumed_items = set(user_ratings[item_col].values)
    item_scores = {}
    for similar_user_idx, similarity in similar_users:
        similar_user_items = user_item_matrix[similar_user_idx].nonzero()[1]
        for item_idx in similar_user_items:
            item_id = [iid for iid, idx in item_id_map.items() if idx == item_idx][0]
            if item_id in consumed_items: continue
            rating = user_item_matrix[similar_user_idx, item_idx]
            if rating >= 4.0:
                if item_id not in item_scores: item_scores[item_id] = {'total_score': 0, 'total_sim': 0}
                item_scores[item_id]['total_score'] += similarity * rating
                item_scores[item_id]['total_sim'] += similarity
    recommendations = []
    for item_id, scores in item_scores.items():
        if scores['total_sim'] > 0:
            fcd_score = scores['total_score'] / scores['total_sim']
            fcd_score_norm = (fcd_score - 1) / 4
            recommendations.append({'item_id': str(item_id), 'fcd_score': fcd_score_norm, 'source': 'fcd', 'n_recommendations': int(scores['total_sim'])})
    recommendations.sort(key=lambda x: x['fcd_score'], reverse=True)
    return recommendations[:top_k]

def reciprocal_rank_fusion(ranked_lists, k=60, weights=None):
    if weights is None: weights = {source: 1.0 for source in ranked_lists.keys()}
    rrf_scores, item_metadata = {}, {}
    for source_name, ranked_items in ranked_lists.items():
        source_weight = weights.get(source_name, 1.0)
        for rank, (item_id, item_data) in enumerate(ranked_items, start=1):
            if item_id not in rrf_scores:
                rrf_scores[item_id] = 0.0
                item_metadata[item_id] = item_data
            rrf_scores[item_id] += source_weight / (k + rank)
    sorted_items = sorted(rrf_scores.items(), key=lambda x: x[1], reverse=True)
    results = []
    for item_id, rrf_score in sorted_items:
        item = item_metadata[item_id].copy()
        item['rrf_score'] = rrf_score
        item['item_id'] = item_id
        results.append(item)
    return results

def calculate_ranking_rrf(validated_items, weights=None):
    if VERBOSE: print(f"\n📊 Ranking con RRF ({len(validated_items)} items)...")
    if not validated_items: return []
    sources = {}
    for item in validated_items:
        source_name = item['llm_source']
        if source_name not in sources: sources[source_name] = []
        sources[source_name].append(item)
    ranked_lists = {}
    for source_name, items in sources.items():
        sorted_items = sorted(items, key=lambda x: x['relevance_score'], reverse=True)
        ranked_lists[source_name] = [(item['title'], item) for item in sorted_items]

    if weights is None: weights = {'llm': 1.0, 'fcd': 1.0}
    rrf_weights = {}
    for source_name in ranked_lists.keys():
        if source_name == 'fcd': rrf_weights[source_name] = weights.get('fcd', 1.0)
        else: rrf_weights[source_name] = weights.get('llm', 1.0)

    results = reciprocal_rank_fusion(ranked_lists, k=60, weights=rrf_weights)
    for item in results:
        item_mentions = []
        for source_name, ranked_list in ranked_lists.items():
            for title, item_data in ranked_list:
                if title == item['item_id']:
                    item_mentions.append(item_data)
                    break
        item['mention_count'] = len(item_mentions)
        item['consensus'] = len(item_mentions) / len(ranked_lists) if len(ranked_lists) > 0 else 0
        if item_mentions: item['relevance'] = sum(m.get('relevance_score', 0.5) for m in item_mentions) / len(item_mentions)
        else: item['relevance'] = item.get('relevance_score', 0.5)
        item['rank_score'] = item['rrf_score']
    if VERBOSE: print(f"   ✅ {len(results)} items únicos rankeados con RRF")
    return results

def two_stage_hybrid_ranking(validated_items, user_id, dataset_name, top_k=10, use_two_stage=True):
    if not use_two_stage or user_id is None:
        ranked = calculate_ranking_rrf(validated_items, weights=None)
        return ranked[:top_k]

    if VERBOSE: print(f"\n🎯 Arquitectura Híbrida de 2 Etapas (user_id={user_id})...")
    if VERBOSE: print("\n   Etapa 1: Relevance Filtering (RRF, sin FCD)...")
    llm_items = [item for item in validated_items if item['llm_source'] != 'fcd']
    if not llm_items:
        if VERBOSE: print("   ⚠️ No hay items de LLMs, usando FCD solo")
        return validated_items[:top_k]

    ranked_relevant = calculate_ranking_rrf(llm_items, weights={'llm': 1.0})
    top_50_relevant = ranked_relevant[:min(50, len(ranked_relevant))]
    if VERBOSE: print(f"      ✅ Top-50 items más relevantes (RRF)")

    if VERBOSE: print("\n   Etapa 2: Personalization Re-Ranking (RRF + FCD)...")
    try:
        ratings_df, user_item_matrix, user_id_map, item_id_map = load_user_ratings(dataset_name)
        fcd_recs_all = fcd_recommendations(user_id, dataset_name, ratings_df, user_item_matrix, user_id_map, item_id_map, top_k=100)
        df_full, _ = load_data(dataset_name, generate_embeddings=False) # Only need the DataFrame, not embeddings
        fcd_scores_map = {}
        for rec in fcd_recs_all:
            matching_items = df_full[df_full['global_item_id'] == rec['item_id']]
            if not matching_items.empty:
                title = matching_items.iloc[0]['title']
                fcd_scores_map[title] = rec['fcd_score']

        personalized_items = []
        for item in top_50_relevant:
            title = item.get('title', item.get('item_id', ''))
            if not title: continue
            rrf_score = item.get('rrf_score', 0.0)
            fcd_score = fcd_scores_map.get(title, 0.0)
            final_score = 0.5 * rrf_score + 0.5 * fcd_score
            item_combined = item.copy()
            item_combined['title'] = title
            item_combined['final_score'] = final_score
            item_combined['rrf_score_normalized'] = rrf_score
            item_combined['fcd_score'] = fcd_score
            personalized_items.append(item_combined)
        personalized_items.sort(key=lambda x: x['final_score'], reverse=True)
        if VERBOSE: print(f"      ✅ Top-{top_k} personalizados (RRF + FCD)")
        return personalized_items[:top_k]

    except Exception as e:
        if VERBOSE:
            print(f"   ⚠️ Error en Etapa 2 (FCD): {e}")
            import traceback
            traceback.print_exc()
        if VERBOSE: print("   ℹ️ Usando solo Etapa 1 (sin personalización FCD)")
        return top_50_relevant[:top_k]

def calculate_ranking(validated_items, weights=None):
    # This is the original, simpler ranking function.
    # For the new `recommend_by_item_type`, we'll prioritize `calculate_ranking_rrf` or `two_stage_hybrid_ranking`.
    # Keeping it here for compatibility if other parts of the notebook call it directly.
    if weights is None: weights = {'llm': 1.0, 'fcd': 0.0}
    if VERBOSE: print(f"\n📊 Ranking ({len(validated_items)} items)...")
    if not validated_items: return []
    has_fcd = any('fcd_score' in item for item in validated_items)

    if has_fcd and weights['fcd'] > 0:
        alpha, beta, gamma = 0.6 * weights['llm'], 0.4 * weights['llm'], weights['fcd']
        if VERBOSE: print(f"   📐 Fórmula: {alpha:.2f}×relevance + {beta:.2f}×consensus + {gamma:.2f}×fcd_score")
    else:
        alpha, beta, gamma = 0.6, 0.4, 0.0
        if VERBOSE: print(f"   📐 Fórmula: {alpha:.2f}×relevance + {beta:.2f}×consensus")

    item_groups = {}
    for item in validated_items:
        title = item['title']
        if title not in item_groups: item_groups[title] = {'mentions': [], 'max_relevance': 0, 'max_fcd_score': 0, 'item_data': item}
        item_groups[title]['mentions'].append(item)
        item_groups[title]['max_relevance'] = max(item_groups[title]['max_relevance'], item['relevance_score'])
        if 'fcd_score' in item: item_groups[title]['max_fcd_score'] = max(item_groups[title]['max_fcd_score'], item['fcd_score'])

    ranked_items = []
    max_mentions = max(len(g['mentions']) for g in item_groups.values()) if item_groups else 0

    for title, data in item_groups.items():
        relevance = data['max_relevance']
        llm_mentions = [m for m in data['mentions'] if m['llm_source'] != 'fcd']
        consensus = len(llm_mentions) / max_mentions if max_mentions > 0 else 0
        fcd_score = data['max_fcd_score']
        sources = [m['llm_source'] for m in data['mentions']]
        has_llm, has_fcd_item = len(llm_mentions) > 0, fcd_score > 0

        if not has_llm and has_fcd_item: rank_score = alpha * relevance * 0.7
        else: rank_score = alpha * relevance + beta * consensus + (gamma * fcd_score if has_fcd_item else 0)

        item = data['item_data']
        ranked_items.append({
            'title': title, 'item_id': item['item_id'], 'description': item['description'], 'rank_score': rank_score,
            'relevance': relevance, 'consensus': consensus, 'fcd_score': fcd_score if fcd_score > 0 else None,
            'mention_count': len(data['mentions']), 'llm_sources': sources, 'llm_reasonings': [m['llm_reasoning'] for m in data['mentions']]
        })
    ranked_items.sort(key=lambda x: x['rank_score'], reverse=True)
    if VERBOSE: print(f"   ✅ {len(ranked_items)} items únicos rankeados")
    return ranked_items

def mmr_diversification(ranked_items, embeddings_map, k=10, lambda_param=0.7):
    if VERBOSE: print(f"\n🎨 Diversificación MMR (k={k}, λ={lambda_param}, vectorizado={USE_VECTORIZED_MMR})...")
    if len(ranked_items) <= k: return ranked_items

    if USE_VECTORIZED_MMR:
        titles = [item['title'] for item in ranked_items]
        embeddings_list = [embeddings_map[title] if title in embeddings_map else np.zeros(encoder.get_sentence_embedding_dimension()) for title in titles]
        embeddings_matrix = np.array(embeddings_list)
        norms = np.linalg.norm(embeddings_matrix, axis=1, keepdims=True)
        norms = np.where(norms == 0, 1e-10, norms)
        embeddings_norm = embeddings_matrix / norms
        relevances = np.array([item['rank_score'] for item in ranked_items])

        selected_indices, remaining_indices = [], list(range(len(ranked_items)))
        first_idx = np.argmax(relevances) # Select highest relevance as first item
        selected_indices.append(remaining_indices.pop(remaining_indices.index(first_idx)))
        if VERBOSE: print(f"   Iter 1: {ranked_items[selected_indices[0]]['title'][:40]:40s} (rank={ranked_items[selected_indices[0]]['rank_score']:.3f})")

        iteration = 2
        while len(selected_indices) < k and remaining_indices:
            selected_embs = embeddings_norm[selected_indices]
            remaining_embs = embeddings_norm[remaining_indices]
            similarities_matrix = remaining_embs @ selected_embs.T
            max_sims = similarities_matrix.max(axis=1)
            diversities = 1 - max_sims
            relevances_remaining = relevances[remaining_indices]
            mmr_scores = lambda_param * relevances_remaining + (1 - lambda_param) * diversities

            best_local_idx = mmr_scores.argmax()
            best_global_idx = remaining_indices.pop(best_local_idx)
            selected_indices.append(best_global_idx)
            if VERBOSE: print(f"   Iter {iteration}: {ranked_items[best_global_idx]['title'][:40]:40s} (mmr={mmr_scores[best_local_idx]:.3f}, rank={ranked_items[best_global_idx]['rank_score']:.3f})")
            iteration += 1
        selected = [ranked_items[idx] for idx in selected_indices]
        if VERBOSE: print(f"   ✅ {len(selected)} items seleccionados con diversidad (vectorizado)")
        return selected
    else: # Fallback to manual loop implementation
        selected, candidates = [], ranked_items.copy()
        if candidates:
            selected.append(candidates.pop(0))
            if VERBOSE: print(f"   Iter 1: {selected[0]['title'][:40]:40s} (rank={selected[0]['rank_score']:.3f})")

        iteration = 2
        while len(selected) < k and candidates:
            best_mmr, best_idx = -1, 0
            for i, candidate in enumerate(candidates):
                relevance = candidate['rank_score']
                cand_title = candidate['title']
                if cand_title not in embeddings_map: diversity = 1.0
                else:
                    cand_emb, similarities = embeddings_map[cand_title], []
                    for sel in selected:
                        sel_title = sel['title']
                        if sel_title in embeddings_map:
                            sel_emb = embeddings_map[sel_title]
                            sim = np.dot(cand_emb, sel_emb) / (np.linalg.norm(cand_emb) * np.linalg.norm(sel_emb) + 1e-10)
                            similarities.append(np.clip(sim, -1.0, 1.0))
                    max_sim = max(similarities) if similarities else 0.0
                    diversity = 1 - max_sim
                mmr_score = lambda_param * relevance + (1 - lambda_param) * diversity
                if mmr_score > best_mmr: best_mmr, best_idx = mmr_score, i
            selected_item = candidates.pop(best_idx)
            selected.append(selected_item)
            if VERBOSE: print(f"   Iter {iteration}: {selected_item['title'][:40]:40s} (mmr={best_mmr:.3f}, rank={selected_item['rank_score']:.3f})")
            iteration += 1
        if VERBOSE: print(f"   ✅ {len(selected)} items seleccionados con diversidad")
        return selected

"""##Validacion Semantica"""

# 4. MODIFIED: semantic_validation to accept target_item_type and filter by it
def semantic_validation(llm_results, query, df, dataset_name, fcd_results=None, weights=None, target_item_type=None):
    if fcd_results is None: fcd_results = {}
    if weights is None: weights = {'llm': 1.0, 'fcd': 0.0}
    config = DATASETS[dataset_name]
    threshold = config['threshold']
    external_threshold = config.get('external_threshold', threshold * 0.85)
    allow_external = config.get('allow_external', False)

    if VERBOSE:
        print(f"\n🔍 Validación Semántica Mejorada:")
        print(f"   Database threshold: {threshold}")
        print(f"   External threshold: {external_threshold}")
        print(f"   Allow external: {allow_external}")
        if target_item_type:
            print(f"   Filtering for item_type: {target_item_type}")

    query_emb = encoder.encode([query])[0]
    validated_items = []
    stats = {
        'total': 0, 'exact_match': 0, 'fuzzy_match': 0, 'external_valid': 0,
        'external_invalid': 0, 'desc_invalid': 0, 'item_invalid': 0,
        'item_type_mismatch': 0, # New stat
    }

    for llm_name, recommendations in llm_results.items():
        for rec in recommendations:
            stats['total'] += 1
            title = rec['recommendation']
            source = rec.get('source', 'database')

            matching_items = df[df['title'].str.contains(title, case=False, regex=False, na=False)]

            item_data = None
            match_type = None
            match_score = 0.0
            is_external = False

            if not matching_items.empty:
                item_data = matching_items.iloc[0]
                if target_item_type and str(item_data['item_type']) != target_item_type:
                    stats['item_type_mismatch'] += 1
                    if VERBOSE: print(f"   ⚠️ Skipping '{title}' from LLM {llm_name} due to mismatched item_type: expected {target_item_type}, got {item_data['item_type']}")
                    continue
                stats['exact_match'] += 1
                match_type = 'exact'
                match_score = 1.0
            else:
                fuzzy_title, fuzzy_score, fuzzy_item = fuzzy_match_title(title, df, threshold=0.85)
                if fuzzy_title:
                    if target_item_type and str(fuzzy_item['item_type']) != target_item_type:
                        stats['item_type_mismatch'] += 1
                        if VERBOSE: print(f"   ⚠️ Skipping '{title}' from LLM {llm_name} due to mismatched item_type: expected {target_item_type}, got {fuzzy_item['item_type']}")
                        continue
                    stats['fuzzy_match'] += 1
                    item_data = fuzzy_item
                    match_type = 'fuzzy'
                    match_score = fuzzy_score
                    if VERBOSE: print(f"   ℹ️ {llm_name}: Fuzzy match '{title}' → '{fuzzy_title}' (score={fuzzy_score:.3f})")
                elif source == 'external' and allow_external:
                    if VERBOSE: print(f"   ℹ️ {llm_name}: External recommendation '{title}' (not in database)")
                    # For external recs, we can't check item_type against our DB.
                    # If `target_item_type` is very strict, external recs might not pass here.
                    # For now, we allow external recs to proceed if `allow_external` is True,
                    # and they are not filtered by `target_item_type` directly at this step.
                    # It would require LLM to provide item_type for external recs to filter.
                    desc_emb = encoder.encode([rec['description']])[0]
                    desc_similarity = np.dot(query_emb, desc_emb) / (np.linalg.norm(query_emb) * np.linalg.norm(desc_emb) + 1e-10)
                    desc_similarity = np.clip(desc_similarity, -1.0, 1.0)
                    desc_similarity_norm = (desc_similarity + 1) / 2
                    if desc_similarity_norm >= external_threshold:
                        stats['external_valid'] += 1
                        validated_items.append({
                            'llm_source': llm_name, 'title': title, 'item_id': f"EXTERNAL_{len(validated_items)}_{llm_name}",
                            'item_type': 'external', # Assign generic type
                            'description': 'External recommendation', 'llm_score': rec['ranking'], 'llm_reasoning': rec['description'],
                            'desc_similarity': desc_similarity_norm, 'item_similarity': desc_similarity_norm * 0.9,
                            'relevance_score': desc_similarity_norm * 0.85, 'match_type': 'external', 'match_score': 0.0,
                            'is_external': True,
                        })
                        continue
                    else:
                        stats['external_invalid'] += 1
                        if VERBOSE: print(f"   ⚠️ {llm_name}: External '{title}' rejected (desc_sim={desc_similarity_norm:.3f} < {external_threshold})")
                        continue
                else:
                    stats['external_invalid'] += 1
                    if VERBOSE: print(f"   ⚠️ {llm_name}: '{title}' not found (no exact/fuzzy match)")
                    continue

            # If we reached here, item_data is from our dataset and passed item_type check
            desc_emb = encoder.encode([rec['description']])[0]
            desc_similarity = np.dot(query_emb, desc_emb) / (np.linalg.norm(query_emb) * np.linalg.norm(desc_emb) + 1e-10)
            desc_similarity = np.clip(desc_similarity, -1.0, 1.0)
            desc_similarity_norm = (desc_similarity + 1) / 2

            if desc_similarity_norm < threshold:
                stats['desc_invalid'] += 1
                if VERBOSE: print(f"   ⚠️ {llm_name}: Description of '{title}' not similar ({desc_similarity_norm:.3f} < {threshold})")
                continue

            item_text = f"{item_data['title']}. {item_data['description']}"
            item_emb = encoder.encode([item_text])[0]
            item_similarity = np.dot(query_emb, item_emb) / (np.linalg.norm(query_emb) * np.linalg.norm(item_emb) + 1e-10)
            item_similarity = np.clip(item_similarity, -1.0, 1.0)
            item_similarity_norm = (item_similarity + 1) / 2

            if item_similarity_norm < threshold:
                stats['item_invalid'] += 1
                if VERBOSE: print(f"   ⚠️ {llm_name}: Item '{title}' not similar ({item_similarity_norm:.3f} < {threshold})")
                continue

            validated_items.append({
                'llm_source': llm_name, 'title': item_data['title'], 'item_id': item_data['item_id'],
                'item_type': item_data['item_type'], # Include item_type
                'description': item_data['description'], 'llm_score': rec['ranking'], 'llm_reasoning': rec['description'],
                'desc_similarity': desc_similarity_norm, 'item_similarity': item_similarity_norm,
                'relevance_score': (desc_similarity_norm + item_similarity_norm) / 2,
                'match_type': match_type, 'match_score': match_score, 'is_external': is_external,
            })

    fcd_stats = {'total': 0, 'valid': 0, 'invalid': 0, 'item_type_mismatch': 0}
    if fcd_results:
        if VERBOSE: print(f"\n🤝 Validando recomendaciones de FCD...")
        query_emb = encoder.encode([query])[0]
        fcd_item_id_col = 'global_item_id' # FCD recs use global_item_id

        for source_name, recommendations in fcd_results.items():
            for fcd_rec in recommendations:
                fcd_stats['total'] += 1
                item_id = fcd_rec['item_id'] # This is global_item_id

                matching_items = df[df[fcd_item_id_col].astype(str) == str(item_id)]

                if matching_items.empty:
                    fcd_stats['invalid'] += 1
                    if VERBOSE: print(f"   ⚠️ FCD: Item {item_id} not found in dataset")
                    continue

                item_data = matching_items.iloc[0]

                # MODIFICATION: Check item_type for FCD match
                if target_item_type and str(item_data['item_type']) != target_item_type:
                    fcd_stats['item_type_mismatch'] += 1
                    if VERBOSE: print(f"   ⚠️ Skipping FCD rec for item '{item_data['title']}' due to mismatched item_type: expected {target_item_type}, got {item_data['item_type']}")
                    continue

                item_text = f"{item_data['title']}. {item_data['description']}"
                item_emb = encoder.encode([item_text])[0]
                item_similarity = np.dot(query_emb, item_emb) / (np.linalg.norm(query_emb) * np.linalg.norm(item_emb) + 1e-10)
                item_similarity = np.clip(item_similarity, -1.0, 1.0)
                item_similarity_norm = (item_similarity + 1) / 2

                fcd_threshold = threshold
                if item_similarity_norm < fcd_threshold:
                    fcd_stats['invalid'] += 1
                    if VERBOSE: print(f"   ⚠️ FCD: Item '{item_data['title']}' not similar ({item_similarity_norm:.3f} < {fcd_threshold:.3f})")
                    continue

                fcd_stats['valid'] += 1
                validated_items.append({
                    'llm_source': 'fcd', 'title': item_data['title'], 'item_id': item_data['item_id'],
                    'item_type': item_data['item_type'], # Include item_type
                    'description': item_data['description'], 'llm_score': 0.0,
                    'llm_reasoning': f"Recommended by collaborative filtering (score: {fcd_rec['fcd_score']:.3f})",
                    'desc_similarity': item_similarity_norm, 'item_similarity': item_similarity_norm,
                    'relevance_score': item_similarity_norm, 'match_type': 'fcd', 'match_score': 1.0,
                    'is_external': False, 'fcd_score': fcd_rec['fcd_score'], 'fcd_n_recs': fcd_rec.get('n_recommendations', 0),
                })
        if fcd_stats['total'] > 0 and VERBOSE:
            print(f"   📊 FCD validados: {fcd_stats['valid']}/{fcd_stats['total']}")

    if VERBOSE:
        print(f"\n   📊 Validación Completa:")
        print(f"      Total LLMs procesados: {stats['total']}")
        print(f"      ✅ Exact matches: {stats['exact_match']}")
        print(f"      ✅ Fuzzy matches: {stats['fuzzy_match']}")
        if allow_external:
            print(f"      ✅ External (valid): {stats['external_valid']}")
            print(f"      ❌ External (invalid): {stats['external_invalid']}")
        print(f"      ❌ Description invalid: {stats['desc_invalid']}")
        print(f"      ❌ Item invalid: {stats['item_invalid']}")
        print(f"      ❌ Item type mismatch: {stats['item_type_mismatch']}") # New stat
        if fcd_stats['total'] > 0:
            print(f"      Total FCD procesados: {fcd_stats['total']}")
            print(f"      ✅ FCD valid: {fcd_stats['valid']}")
            print(f"      ❌ FCD invalid: {fcd_stats['invalid']}")
            print(f"      ❌ FCD item type mismatch: {fcd_stats['item_type_mismatch']}") # New stat
        print(f"      ✅ TOTAL VALIDATED: {len(validated_items)}")

    return validated_items

"""##Funcion de recomendación por tipo"""

# 5. NEW FUNCTION: recommend_by_item_type
def recommend_by_item_type(query, user_id, top_k_by_type, dataset_name='serious_games'):
    """
    Recomienda items de tipos específicos basándose en la query y las preferencias del usuario.

    Args:
        query (str): La consulta del usuario.
        user_id (int): ID del usuario para personalización FCD. Puede ser None.
        top_k_by_type (dict): Diccionario con el formato {'item_type': k_recs}.
                               Ej: {'dynamics': 3, 'mechanics': 5, 'elements': 4}
        dataset_name (str): Nombre del dataset (por defecto 'serious_games').

    Returns:
        dict: Un diccionario con recomendaciones agrupadas por 'item_type'.
              Ej: {'dynamics': [...], 'mechanics': [...], 'elements': [...]}
    """
    print(f"\n🚀 Iniciando recomendación por tipo de ítem para query: '{query}'")
    print(f"   Solicitando: {top_k_by_type}")

    # 1. Cargar el DataFrame y la colección ChromaDB una sola vez
    df_full = load_data_gamification()
    collection = load_or_create_collection(dataset_name)

    # 2. Pre-computar resultados FCD para todo el dataset si user_id está presente
    fcd_data_precomputed = None
    if user_id is not None:
        try:
            print("   Pre-calculando FCD para todo el dataset...")
            ratings_df_full, user_item_matrix_full, user_id_map_full, item_id_map_full = load_user_ratings(dataset_name)
            fcd_data_precomputed = fcd_recommendations(user_id, dataset_name, ratings_df_full,
                                                       user_item_matrix_full, user_id_map_full, item_id_map_full,
                                                       top_k=200) # Get a large pool of FCD recs
            print(f"   ✅ {len(fcd_data_precomputed)} FCD resultados pre-calculados.")
        except Exception as e:
            print(f"   ☑′ FCD component for pre-computation skipped: {e}")

    final_recommendations_by_type = {}

    for item_type, top_k_for_type in top_k_by_type.items():
        print(f"\n--- Generando recomendaciones para item_type: '{item_type}' (top_k={top_k_for_type}) ---")

        # Calculate dynamic weights for the current user (if any)
        weights = calculate_weights(user_id=user_id, dataset_name=dataset_name)

        # Perform RAG retrieval with 'where' clause for the current item_type
        candidates = rag_retrieval(query, collection, top_k=TOP_K_CANDIDATES, where={'item_type': item_type.lower()})

        # Query all LLMs with these type-specific candidates
        llm_results_for_type = query_all_llms(query, candidates, dataset_name)

        # Filter pre-computed FCD recommendations for the current item_type
        fcd_results_for_type = {}
        if fcd_data_precomputed:
            fcd_recs_enriched = []
            for rec in fcd_data_precomputed:
                # Find the item_type for this item_id from df_full
                matching_row = df_full[df_full['global_item_id'] == rec['item_id']]
                if not matching_row.empty:
                    rec_item_type = matching_row.iloc[0]['item_type']
                    if rec_item_type.lower() == item_type.lower():
                        enriched_rec = rec.copy()
                        enriched_rec['item_type'] = rec_item_type # Add item_type
                        fcd_recs_enriched.append(enriched_rec)
            fcd_results_for_type['fcd'] = fcd_recs_enriched
            print(f"   ✅ {len(fcd_recs_enriched)} FCD resultados filtrados para '{item_type}'.")


        # Call modified semantic_validation passing target_item_type
        validated_for_type = semantic_validation(
            llm_results_for_type, query, df_full, dataset_name,
            fcd_results=fcd_results_for_type, weights=weights,
            target_item_type=item_type.lower() # Pass target_item_type here
        )

        if not validated_for_type:
            print(f"   ☑′ No items validated for type '{item_type}'. Skipping ranking and diversification.")
            final_recommendations_by_type[item_type] = []
            continue

        # Apply ranking (using RRF, or two-stage hybrid if user_id)
        if user_id is not None:
            ranked_for_type = two_stage_hybrid_ranking(validated_for_type, user_id, dataset_name, top_k=top_k_for_type * 2, use_two_stage=True)
        else:
            ranked_for_type = calculate_ranking_rrf(validated_for_type, weights={'llm': 1.0, 'fcd': 0.0})

        if not ranked_for_type:
            print(f"   ☑′ No items ranked for type '{item_type}'.")
            final_recommendations_by_type[item_type] = []
            continue

        # Prepare embeddings map for MMR
        embeddings_map_for_mmr = {
            item['title']: encoder.encode([f"{item['title']}. {item['description']}"])[0]
            for item in ranked_for_type if 'title' in item and 'description' in item
        }
        # Apply diversity (MMR)
        diversified_for_type = mmr_diversification(
            ranked_for_type, embeddings_map_for_mmr, k=top_k_for_type, lambda_param=DATASETS[dataset_name]['mmr_lambda']
        )

        final_recommendations_by_type[item_type] = diversified_for_type

    print("\n✅ Proceso de recomendación por tipo de ítem completado.")
    return final_recommendations_by_type

# 3. Force ChromaDB recreation
