extracted_capability = extracted_items_dict.get("Capability", "Not found")
extracted_learning_objective = extracted_items_dict.get("Learning Objective", "Not found")
extracted_cognitive_function = extracted_items_dict.get("Cognitive Function", "Not found")
extracted_emotion = extracted_items_dict.get("Emotion", "Not found")
extracted_vark_style = extracted_items_dict.get("VARK Style", "Not found")
