"""## Construct New LLM Prompt

### Subtask:
Dynamically build a new comprehensive LLM prompt using the extracted input items to strictly adhere to the user's requested output structure for 'Gamified Dynamics' (Progression, Emotion, Cognitive Function, Motivational), 'Gamified Mechanics', 'Gamification Elements', and 'Narrative'. The prompt will instruct the LLM to generate the concept in English and in a structured JSON format.

**Reasoning**:
The subtask requires building a new LLM prompt with specific placeholders and a detailed JSON output structure. I will define the template string and then format it with the extracted variables, finally printing the result for verification.
"""

GAME_CONCEPT_PROMPT_TEMPLATE = """
As an expert in gamified serious games design, your task is to create a comprehensive serious game concept based on the user's detailed requirements and context.

User's Detailed Requirements:
Context: {context}
Sector: {sector}
Users: {users}
Capability: {capability}
Learning Objective: {learning_objective}
Cognitive Function: {cognitive_function}
Emotion: {emotion}
VARK Style: {vark_style}
Learning Activities: {learning_activities}
Learning Resources: {learning_resources}
Serious Game Description: {serious_game}
Basic Mechanics: {basic_mechanics}
Predominant Motivation: {predominant_motivation}
User Profile: {user_profile}

Instructions for Game Concept Generation:
1. Generate the game concept exclusively in English.
2. Ensure the output is a valid JSON object. Do not include any text before or after the JSON.
3. The game concept must integrate all provided details into a cohesive and engaging design.
4. Strictly adhere to the specified JSON structure below.

Output JSON Format:
{{
  "Game Title": "Your compelling game title",
  "Overall Concept": "A detailed description of the game's core idea, integrating the context, sector, users, and overall learning objective.",
  "Core Mechanics": [
    "Description of a core gameplay mechanic, integrating basic mechanics.",
    "Another core gameplay mechanic, integrating basic mechanics."
  ],
  "Dynamics": {{
    "progression": "Description of how players advance and experience flow, integrating learning objective and predominant motivation.",
    "emotion": "Description of the emotional journey and player feelings, integrating the specified emotion.",
    "cognitive": "Description of cognitive challenges and mental processes involved, integrating cognitive function.",
    "motivation": "Description of what drives players to engage and persist, integrating predominant motivation."
  }},
  "Narrative": "A captivating story or scenario that provides context and purpose, integrating serious game description.",
  "Elements": [
    "Description of a tangible game component, integrating learning resources.",
    "Another tangible game component, integrating VARK style or learning activities."
  ],
  "Target Skills": [
    "The primary capability the game aims to develop, integrating capability.",
    "Another key skill the game aims to develop, integrating learning objective or cognitive function."
  ]
}}
"""

# Fill the template with extracted values
final_game_concept_prompt = GAME_CONCEPT_PROMPT_TEMPLATE.format(
    context=extracted_context,
    sector=extracted_sector,
    users=extracted_users,
    capability=extracted_capability,
    learning_objective=extracted_learning_objective,
    cognitive_function=extracted_cognitive_function,
    emotion=extracted_emotion,
    vark_style=extracted_vark_style,
    learning_activities=extracted_learning_activities,
    learning_resources=extracted_learning_resources,
    serious_game=extracted_serious_game,
    basic_mechanics=extracted_basic_mechanics,
    predominant_motivation=extracted_predominant_motivation,
    user_profile=extracted_user_profile
)

# Print the final prompt for verification
print("--- Final LLM Prompt for Game Concept Generation ---")
print(final_game_concept_prompt)
print("----------------------------------------------------")

